19	// Claude Code hook names - these become subcommands under `entire hooks claude-code`
20	const (
21		HookNameSessionStart     = "session-start"
22		HookNameSessionEnd       = "session-end"
23		HookNameStop             = "stop"
24		HookNameUserPromptSubmit = "user-prompt-submit"
