30	// ClaudeSettingsFileName is the settings file used by Claude Code.
31	// This is Claude-specific and not shared with other agents.
32	const ClaudeSettingsFileName = "settings.json"
33	
34	// metadataDenyRule blocks Claude from reading Entire session metadata
35	const metadataDenyRule = "Read(./.entire/metadata/**)"
36	
37	// entireHookPrefixes are command prefixes that identify Entire hooks (both old and new formats)
38	var entireHookPrefixes = []string{
39		"entire ",
40		"go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go ",
