43	// InstallHooks installs Claude Code hooks in .claude/settings.json.
44	// If force is true, removes existing Entire hooks before installing.
45	// Returns the number of hooks installed.
46	func (c *ClaudeCodeAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
47		// Use repo root instead of CWD to find .claude directory
48		// This ensures hooks are installed correctly when run from a subdirectory
49		repoRoot, err := paths.WorktreeRoot(ctx)
50		if err != nil {
51			// Fallback to CWD if not in a git repo (e.g., during tests)
52			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
53			if err != nil {
54				return 0, fmt.Errorf("failed to get current directory: %w", err)
55			}
56		}
57	
58		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
59	
60		// Read existing settings if they exist
61		var rawSettings map[string]json.RawMessage
62	
63		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
64		var rawHooks map[string]json.RawMessage
65	
66		// rawPermissions preserves unknown permission fields (e.g., "ask")
67		var rawPermissions map[string]json.RawMessage
68	
69		existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + settings file name
70		if readErr == nil {
71			if err := json.Unmarshal(existingData, &rawSettings); err != nil {
72				return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
73			}
74			if hooksRaw, ok := rawSettings["hooks"]; ok {
75				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
76					return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
77				}
78			}
79			if permRaw, ok := rawSettings["permissions"]; ok {
80				if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
81					return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
82				}
83			}
84		} else {
85			rawSettings = make(map[string]json.RawMessage)
86		}
87	
88		if rawHooks == nil {
89			rawHooks = make(map[string]json.RawMessage)
90		}
91		if rawPermissions == nil {
92			rawPermissions = make(map[string]json.RawMessage)
93		}
94	
95		// Parse only the hook types we need to modify
96		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
97		parseHookType(rawHooks, "SessionStart", &sessionStart)
98		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
99		parseHookType(rawHooks, "Stop", &stop)
100		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
101		parseHookType(rawHooks, "PreToolUse", &preToolUse)
102		parseHookType(rawHooks, "PostToolUse", &postToolUse)
103	
104		// If force is true, remove all existing Entire hooks first
105		if force {
106			sessionStart = removeEntireHooks(sessionStart)
107			sessionEnd = removeEntireHooks(sessionEnd)
108			stop = removeEntireHooks(stop)
109			userPromptSubmit = removeEntireHooks(userPromptSubmit)
110			preToolUse = removeEntireHooksFromMatchers(preToolUse)
111			postToolUse = removeEntireHooksFromMatchers(postToolUse)
112		}
113	
114		// Define hook commands
115		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
116		if localDev {
117			sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
118			sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
119			stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
120			userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
121			preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
122			postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
123			postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
124		} else {
125			sessionStartCmd = agent.WrapProductionJSONWarningHookCommand("entire hooks claude-code session-start", agent.WarningFormatMultiLine)
126			sessionEndCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code session-end")
127			stopCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code stop")
128			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code user-prompt-submit")
129			preTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code pre-task")
130			postTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-task")
131			postTodoCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-todo")
132		}
133	
134		count := 0
135	
136		// Add hooks if they don't exist
137		if !hookCommandExists(sessionStart, sessionStartCmd) {
138			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
139			count++
140		}
141		if !hookCommandExists(sessionEnd, sessionEndCmd) {
142			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
143			count++
144		}
145		if !hookCommandExists(stop, stopCmd) {
146			stop = addHookToMatcher(stop, "", stopCmd)
147			count++
148		}
149		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
150			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
151			count++
152		}
153		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
154			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
155			count++
156		}
157		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
158			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
159			count++
160		}
161		if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
162			postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
163			count++
164		}
165	
166		// Add permissions.deny rule if not present
167		permissionsChanged := false
168		var denyRules []string
169		if denyRaw, ok := rawPermissions["deny"]; ok {
170			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
171				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
172			}
173		}
174		if !slices.Contains(denyRules, metadataDenyRule) {
175			denyRules = append(denyRules, metadataDenyRule)
176			denyJSON, err := json.Marshal(denyRules)
177			if err != nil {
178				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
179			}
180			rawPermissions["deny"] = denyJSON
181			permissionsChanged = true
182		}
183	
184		if count == 0 && !permissionsChanged {
185			return 0, nil // All hooks and permissions already installed
186		}
187	
188		// Marshal modified hook types back to rawHooks
189		marshalHookType(rawHooks, "SessionStart", sessionStart)
190		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
191		marshalHookType(rawHooks, "Stop", stop)
192		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
193		marshalHookType(rawHooks, "PreToolUse", preToolUse)
194		marshalHookType(rawHooks, "PostToolUse", postToolUse)
195	
196		// Marshal hooks and update raw settings
197		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
198		if err != nil {
199			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
200		}
201		rawSettings["hooks"] = hooksJSON
202	
203		// Marshal permissions and update raw settings
204		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
205		if err != nil {
206			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
207		}
208		rawSettings["permissions"] = permJSON
209	
210		// Write back to file
211		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
212			return 0, fmt.Errorf("failed to create .claude directory: %w", err)
213		}
214	
215		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
216		if err != nil {
217			return 0, fmt.Errorf("failed to marshal settings: %w", err)
218		}
219	
220		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
221			return 0, fmt.Errorf("failed to write settings.json: %w", err)
222		}
223	
224		return count, nil
225	}
