250	// UninstallHooks removes Entire hooks from Claude Code settings.
251	func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
252		// Use repo root to find .claude directory when run from a subdirectory
253		repoRoot, err := paths.WorktreeRoot(ctx)
254		if err != nil {
255			repoRoot = "." // Fallback to CWD if not in a git repo
256		}
257		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
258		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
259		if err != nil {
260			return nil //nolint:nilerr // No settings file means nothing to uninstall
261		}
262	
263		var rawSettings map[string]json.RawMessage
264		if err := json.Unmarshal(data, &rawSettings); err != nil {
265			return fmt.Errorf("failed to parse settings.json: %w", err)
266		}
267	
268		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
269		var rawHooks map[string]json.RawMessage
270		if hooksRaw, ok := rawSettings["hooks"]; ok {
271			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
272				return fmt.Errorf("failed to parse hooks: %w", err)
273			}
274		}
275		if rawHooks == nil {
276			rawHooks = make(map[string]json.RawMessage)
277		}
278	
279		// Parse only the hook types we need to modify
280		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
281		parseHookType(rawHooks, "SessionStart", &sessionStart)
282		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
283		parseHookType(rawHooks, "Stop", &stop)
284		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
285		parseHookType(rawHooks, "PreToolUse", &preToolUse)
286		parseHookType(rawHooks, "PostToolUse", &postToolUse)
287	
288		// Remove Entire hooks from all hook types
289		sessionStart = removeEntireHooks(sessionStart)
290		sessionEnd = removeEntireHooks(sessionEnd)
291		stop = removeEntireHooks(stop)
292		userPromptSubmit = removeEntireHooks(userPromptSubmit)
293		preToolUse = removeEntireHooksFromMatchers(preToolUse)
294		postToolUse = removeEntireHooksFromMatchers(postToolUse)
295	
296		// Marshal modified hook types back to rawHooks
297		marshalHookType(rawHooks, "SessionStart", sessionStart)
298		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
299		marshalHookType(rawHooks, "Stop", stop)
300		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
301		marshalHookType(rawHooks, "PreToolUse", preToolUse)
302		marshalHookType(rawHooks, "PostToolUse", postToolUse)
303	
304		// Also remove the metadata deny rule from permissions
305		var rawPermissions map[string]json.RawMessage
306		if permRaw, ok := rawSettings["permissions"]; ok {
307			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
308				// If parsing fails, just skip permissions cleanup
309				rawPermissions = nil
310			}
311		}
312	
313		if rawPermissions != nil {
314			if denyRaw, ok := rawPermissions["deny"]; ok {
315				var denyRules []string
316				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
317					// Filter out the metadata deny rule
318					filteredRules := make([]string, 0, len(denyRules))
319					for _, rule := range denyRules {
320						if rule != metadataDenyRule {
321							filteredRules = append(filteredRules, rule)
322						}
323					}
324					if len(filteredRules) > 0 {
325						denyJSON, err := json.Marshal(filteredRules)
326						if err == nil {
327							rawPermissions["deny"] = denyJSON
328						}
329					} else {
330						// Remove empty deny array
331						delete(rawPermissions, "deny")
332					}
333				}
334			}
335	
336			// If permissions is empty, remove it entirely
337			if len(rawPermissions) > 0 {
338				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
339				if err == nil {
340					rawSettings["permissions"] = permJSON
341				}
342			} else {
343				delete(rawSettings, "permissions")
344			}
345		}
346	
347		// Marshal hooks back (preserving unknown hook types)
348		if len(rawHooks) > 0 {
349			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
350			if err != nil {
351				return fmt.Errorf("failed to marshal hooks: %w", err)
352			}
353			rawSettings["hooks"] = hooksJSON
354		} else {
355			delete(rawSettings, "hooks")
356		}
357	
358		// Write back
359		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
360		if err != nil {
361			return fmt.Errorf("failed to marshal settings: %w", err)
362		}
363		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
364			return fmt.Errorf("failed to write settings.json: %w", err)
365		}
366		return nil
367	}
