369	// AreHooksInstalled checks if Entire hooks are installed.
370	func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
371		// Use repo root to find .claude directory when run from a subdirectory
372		repoRoot, err := paths.WorktreeRoot(ctx)
373		if err != nil {
374			repoRoot = "." // Fallback to CWD if not in a git repo
375		}
376		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
377		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
378		if err != nil {
379			return false
380		}
381	
382		var settings ClaudeSettings
383		if err := json.Unmarshal(data, &settings); err != nil {
384			return false
385		}
386	
387		// Check for at least one of our hooks (new, wrapped, or legacy format)
388		return hasEntireHook(settings.Hooks.Stop)
389	}
