391	// Helper functions for hook management
392	
393	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
394		for _, matcher := range matchers {
395			for _, hook := range matcher.Hooks {
396				if hook.Command == command {
397					return true
398				}
399			}
400		}
401		return false
402	}
403	
404	func hasEntireHook(matchers []ClaudeHookMatcher) bool {
405		for _, matcher := range matchers {
406			for _, hook := range matcher.Hooks {
407				if isEntireHook(hook.Command) {
408					return true
409				}
410			}
411		}
412		return false
413	}
414	
415	func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
416		for _, matcher := range matchers {
417			if matcher.Matcher == matcherName {
418				for _, hook := range matcher.Hooks {
419					if hook.Command == command {
420						return true
421					}
422				}
423			}
424		}
425		return false
426	}
427	
428	func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
429		entry := ClaudeHookEntry{
430			Type:    "command",
431			Command: command,
432		}
433	
434		// If no matcher name, add to a matcher with empty string
435		if matcherName == "" {
436			for i, matcher := range matchers {
437				if matcher.Matcher == "" {
438					matchers[i].Hooks = append(matchers[i].Hooks, entry)
439					return matchers
440				}
441			}
442			return append(matchers, ClaudeHookMatcher{
443				Matcher: "",
444				Hooks:   []ClaudeHookEntry{entry},
445			})
446		}
447	
448		// Find or create matcher with the given name
449		for i, matcher := range matchers {
450			if matcher.Matcher == matcherName {
451				matchers[i].Hooks = append(matchers[i].Hooks, entry)
452				return matchers
453			}
454		}
455	
456		return append(matchers, ClaudeHookMatcher{
457			Matcher: matcherName,
458			Hooks:   []ClaudeHookEntry{entry},
459		})
460	}
461	
462	// isEntireHook checks if a command is an Entire hook (old or new format)
463	func isEntireHook(command string) bool {
464		return agent.IsManagedHookCommand(command, entireHookPrefixes)
465	}
466	
467	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
468	func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
469		result := make([]ClaudeHookMatcher, 0, len(matchers))
470		for _, matcher := range matchers {
471			filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
472			for _, hook := range matcher.Hooks {
473				if !isEntireHook(hook.Command) {
474					filteredHooks = append(filteredHooks, hook)
475				}
476			}
477			// Only keep the matcher if it has hooks remaining
478			if len(filteredHooks) > 0 {
479				matcher.Hooks = filteredHooks
480				result = append(result, matcher)
481			}
482		}
483		return result
484	}
485	
486	// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
487	// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
488	func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
489		// Same logic as removeEntireHooks - both work on the same structure
490		return removeEntireHooks(matchers)
491	}
