54	// InstallHooks installs Cursor hooks in .cursor/hooks.json.
55	// If force is true, removes existing Entire hooks before installing.
56	// Returns the number of hooks installed.
57	// Unknown top-level fields and hook types are preserved on round-trip.
58	func (c *CursorAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
59		worktreeRoot, err := paths.WorktreeRoot(ctx)
60		if err != nil {
61			worktreeRoot = "."
62		}
63	
64		hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
65	
66		// Use raw maps to preserve unknown fields on round-trip
67		var rawFile map[string]json.RawMessage
68		var rawHooks map[string]json.RawMessage
69	
70		existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
71		if readErr == nil {
72			if err := json.Unmarshal(existingData, &rawFile); err != nil {
73				return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
74			}
75			if hooksRaw, ok := rawFile["hooks"]; ok {
76				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
77					return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
78				}
79			}
80			if _, ok := rawFile["version"]; !ok {
81				rawFile["version"] = json.RawMessage(`1`)
82			}
83		} else {
84			rawFile = map[string]json.RawMessage{
85				"version": json.RawMessage(`1`),
86			}
87		}
88	
89		if rawHooks == nil {
90			rawHooks = make(map[string]json.RawMessage)
91		}
92	
93		// Parse only the hook types we manage
94		var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
95		parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
96		parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
97		parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
98		parseCursorHookType(rawHooks, "stop", &stop)
99		parseCursorHookType(rawHooks, "preCompact", &preCompact)
100		parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
101		parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
102	
103		// If force is true, remove all existing Entire hooks first
104		if force {
105			sessionStart = removeEntireHooks(sessionStart)
106			sessionEnd = removeEntireHooks(sessionEnd)
107			beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
108			stop = removeEntireHooks(stop)
109			preCompact = removeEntireHooks(preCompact)
110			subagentStart = removeEntireHooks(subagentStart)
111			subagentStop = removeEntireHooks(subagentStop)
112		}
113	
114		// Define hook commands
115		var cmdPrefix string
116		if localDev {
117			cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks cursor `
118		} else {
119			cmdPrefix = "entire hooks cursor "
120		}
121	
122		sessionStartCmd := cmdPrefix + HookNameSessionStart
123		sessionEndCmd := cmdPrefix + HookNameSessionEnd
124		beforeSubmitPromptCmd := cmdPrefix + HookNameBeforeSubmitPrompt
125		stopCmd := cmdPrefix + HookNameStop
126		preCompactCmd := cmdPrefix + HookNamePreCompact
127		subagentStartCmd := cmdPrefix + HookNameSubagentStart
128		subagentEndCmd := cmdPrefix + HookNameSubagentStop
129		if !localDev {
130			sessionStartCmd = agent.WrapProductionSilentHookCommand(sessionStartCmd)
131			sessionEndCmd = agent.WrapProductionSilentHookCommand(sessionEndCmd)
132			beforeSubmitPromptCmd = agent.WrapProductionSilentHookCommand(beforeSubmitPromptCmd)
133			stopCmd = agent.WrapProductionSilentHookCommand(stopCmd)
134			preCompactCmd = agent.WrapProductionSilentHookCommand(preCompactCmd)
135			subagentStartCmd = agent.WrapProductionSilentHookCommand(subagentStartCmd)
136			subagentEndCmd = agent.WrapProductionSilentHookCommand(subagentEndCmd)
137		}
138	
139		count := 0
140	
141		// Add hooks if they don't exist
142		if !hookCommandExists(sessionStart, sessionStartCmd) {
143			sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
144			count++
145		}
146		if !hookCommandExists(sessionEnd, sessionEndCmd) {
147			sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
148			count++
149		}
150		if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
151			beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
152			count++
153		}
154		if !hookCommandExists(stop, stopCmd) {
155			stop = append(stop, CursorHookEntry{Command: stopCmd})
156			count++
157		}
158		if !hookCommandExists(preCompact, preCompactCmd) {
159			preCompact = append(preCompact, CursorHookEntry{Command: preCompactCmd})
160			count++
161		}
162		if !hookCommandExists(subagentStart, subagentStartCmd) {
163			subagentStart = append(subagentStart, CursorHookEntry{Command: subagentStartCmd})
164			count++
165		}
166		if !hookCommandExists(subagentStop, subagentEndCmd) {
167			subagentStop = append(subagentStop, CursorHookEntry{Command: subagentEndCmd})
168			count++
169		}
170	
171		if count == 0 {
172			return 0, nil
173		}
174	
175		// Marshal modified hook types back into rawHooks
176		marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
177		marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
178		marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
179		marshalCursorHookType(rawHooks, "stop", stop)
180		marshalCursorHookType(rawHooks, "preCompact", preCompact)
181		marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
182		marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
183	
184		// Marshal hooks and update raw file
185		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
186		if err != nil {
187			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
188		}
189		rawFile["hooks"] = hooksJSON
190	
191		// Write to file
192		if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
193			return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
194		}
195	
196		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
197		if err != nil {
198			return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
199		}
200	
201		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
202			return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
203		}
204	
205		return count, nil
206	}
