17	// HooksFileName is the hooks file managed by Entire for Copilot CLI.
18	const HooksFileName = "entire.json"
19	
20	// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
21	const hooksDir = ".github/hooks"
22	
23	// entireHookPrefixes are command prefixes that identify Entire hooks in the bash field.
24	var entireHookPrefixes = []string{
25		"entire ",
26		`go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go `,
27	}
28	
29	// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
30	var hookConfigKey = map[string]string{
31		HookNameUserPromptSubmitted: "userPromptSubmitted",
32		HookNameSessionStart:        "sessionStart",
33		HookNameAgentStop:           "agentStop",
34		HookNameSessionEnd:          "sessionEnd",
35		HookNameSubagentStop:        "subagentStop",
36		HookNamePreToolUse:          "preToolUse",
37		HookNamePostToolUse:         "postToolUse",
38		HookNameErrorOccurred:       "errorOccurred",
39	}
