173		data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
174		if err != nil {
175			if errors.Is(err, os.ErrNotExist) {
176				return nil // No hooks file means nothing to uninstall
177			}
178			return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
179		}
180	
181		var rawFile map[string]json.RawMessage
182		if err := json.Unmarshal(data, &rawFile); err != nil {
183			return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
184		}
185	
186		var rawHooks map[string]json.RawMessage
187		if hooksRaw, ok := rawFile["hooks"]; ok {
