203			entries = removeEntireHooks(entries)
204			if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
205				return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
206			}
207		}
208	
209		// Marshal hooks back (preserving unknown hook types)
210		if len(rawHooks) > 0 {
211			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
212			if err != nil {
213				return fmt.Errorf("failed to marshal hooks: %w", err)
214			}
215			rawFile["hooks"] = hooksJSON
216		} else {
217			delete(rawFile, "hooks")
218		}
219	
220		// Write back
221		output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
222		if err != nil {
223			return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
224		}
225	
226		if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
227			return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
228		}
