45	// InstallHooks installs Factory AI Droid hooks in .factory/settings.json.
46	// If force is true, removes existing Entire hooks before installing.
47	// Returns the number of hooks installed.
48	//
49	//nolint:maintidx // Hook installation is intentionally centralized here; splitting it further would add churn for a config-assembly path.
50	func (f *FactoryAIDroidAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
51		// Use repo root instead of CWD to find .factory directory
52		// This ensures hooks are installed correctly when run from a subdirectory
53		repoRoot, err := paths.WorktreeRoot(ctx)
54		if err != nil {
55			// Fallback to CWD if not in a git repo (e.g., during tests)
56			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
57			if err != nil {
58				return 0, fmt.Errorf("failed to get current directory: %w", err)
59			}
60		}
61	
62		settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
63	
64		// Read existing settings if they exist
65		var rawSettings map[string]json.RawMessage
66	
67		// rawHooks preserves unknown hook types
68		var rawHooks map[string]json.RawMessage
69	
70		// rawPermissions preserves unknown permission fields (e.g., "ask")
71		var rawPermissions map[string]json.RawMessage
72	
73		existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
74		if readErr == nil {
75			if err := json.Unmarshal(existingData, &rawSettings); err != nil {
76				return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
77			}
78			if hooksRaw, ok := rawSettings["hooks"]; ok {
79				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
80					return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
81				}
82			}
83			if permRaw, ok := rawSettings["permissions"]; ok {
84				if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
85					return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
86				}
87			}
88		} else {
89			rawSettings = make(map[string]json.RawMessage)
90		}
91	
92		if rawHooks == nil {
93			rawHooks = make(map[string]json.RawMessage)
94		}
95		if rawPermissions == nil {
96			rawPermissions = make(map[string]json.RawMessage)
97		}
98	
99		// Parse only the hook types we need to modify
100		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
101		parseHookType(rawHooks, "SessionStart", &sessionStart)
102		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
103		parseHookType(rawHooks, "Stop", &stop)
104		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
105		parseHookType(rawHooks, "PreToolUse", &preToolUse)
106		parseHookType(rawHooks, "PostToolUse", &postToolUse)
107		parseHookType(rawHooks, "PreCompact", &preCompact)
108	
109		// If force is true, remove all existing Entire hooks first
110		if force {
111			sessionStart = removeEntireHooks(sessionStart)
112			sessionEnd = removeEntireHooks(sessionEnd)
113			stop = removeEntireHooks(stop)
114			userPromptSubmit = removeEntireHooks(userPromptSubmit)
115			preToolUse = removeEntireHooks(preToolUse)
116			postToolUse = removeEntireHooks(postToolUse)
117			preCompact = removeEntireHooks(preCompact)
118		}
119	
120		// Define hook commands
121		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
122		localDevPrefix := `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go hooks factoryai-droid `
123		if localDev {
124			sessionStartCmd = localDevPrefix + "session-start"
125			sessionEndCmd = localDevPrefix + "session-end"
126			stopCmd = localDevPrefix + "stop"
127			userPromptSubmitCmd = localDevPrefix + "user-prompt-submit"
128			preTaskCmd = localDevPrefix + "pre-tool-use"
129			postTaskCmd = localDevPrefix + "post-tool-use"
130			preCompactCmd = localDevPrefix + "pre-compact"
131		} else {
132			sessionStartCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid session-start")
133			sessionEndCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid session-end")
134			stopCmd = agent.WrapProductionPlainTextWarningHookCommand("entire hooks factoryai-droid stop", agent.WarningFormatSingleLine)
135			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid user-prompt-submit")
136			preTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid pre-tool-use")
137			postTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid post-tool-use")
138			preCompactCmd = agent.WrapProductionSilentHookCommand("entire hooks factoryai-droid pre-compact")
139		}
140	
141		count := 0
142	
143		// Add hooks if they don't exist
144		if !hookCommandExists(sessionStart, sessionStartCmd) {
145			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
146			count++
147		}
148		// Also install user-prompt-submit on SessionStart to ensure TurnStart fires
149		// even when UserPromptSubmit doesn't (e.g., droid exec mode).
150		// The user-prompt-submit handler gracefully handles SessionStart's stdin format
151		// (userPromptSubmitRaw is a superset of sessionInfoRaw; Prompt defaults to "").
152		if !hookCommandExists(sessionStart, userPromptSubmitCmd) {
153			sessionStart = addHookToMatcher(sessionStart, "", userPromptSubmitCmd)
154			count++
155		}
156		if !hookCommandExists(sessionEnd, sessionEndCmd) {
157			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
158			count++
159		}
160		if !hookCommandExists(stop, stopCmd) {
161			stop = addHookToMatcher(stop, "", stopCmd)
162			count++
163		}
164		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
165			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
166			count++
167		}
168		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
169			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
170			count++
171		}
172		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
173			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
174			count++
175		}
176		if !hookCommandExists(preCompact, preCompactCmd) {
177			preCompact = addHookToMatcher(preCompact, "", preCompactCmd)
178			count++
179		}
180	
181		// Add permissions.deny rule if not present
182		permissionsChanged := false
183		var denyRules []string
184		if denyRaw, ok := rawPermissions["deny"]; ok {
185			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
186				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
187			}
188		}
189		if !slices.Contains(denyRules, metadataDenyRule) {
190			denyRules = append(denyRules, metadataDenyRule)
191			denyJSON, err := json.Marshal(denyRules)
192			if err != nil {
193				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
194			}
195			rawPermissions["deny"] = denyJSON
196			permissionsChanged = true
197		}
198	
199		if count == 0 && !permissionsChanged {
200			return 0, nil // All hooks and permissions already installed
201		}
202	
203		// Marshal modified hook types back to rawHooks
204		marshalHookType(rawHooks, "SessionStart", sessionStart)
205		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
206		marshalHookType(rawHooks, "Stop", stop)
207		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
208		marshalHookType(rawHooks, "PreToolUse", preToolUse)
209		marshalHookType(rawHooks, "PostToolUse", postToolUse)
210		marshalHookType(rawHooks, "PreCompact", preCompact)
211	
212		// Marshal hooks and update raw settings
213		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
214		if err != nil {
215			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
216		}
217		rawSettings["hooks"] = hooksJSON
218	
219		// Marshal permissions and update raw settings
220		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
221		if err != nil {
222			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
223		}
224		rawSettings["permissions"] = permJSON
225	
226		// Write back to file
227		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
228			return 0, fmt.Errorf("failed to create .factory directory: %w", err)
229		}
230	
231		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
232		if err != nil {
233			return 0, fmt.Errorf("failed to marshal settings: %w", err)
234		}
235	
236		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
237			return 0, fmt.Errorf("failed to write settings.json: %w", err)
238		}
239	
240		return count, nil
241	}
