266	// UninstallHooks removes Entire hooks from Factory AI Droid settings.
267	func (f *FactoryAIDroidAgent) UninstallHooks(ctx context.Context) error {
268		// Use repo root to find .factory directory when run from a subdirectory
269		repoRoot, err := paths.WorktreeRoot(ctx)
270		if err != nil {
271			repoRoot = "." // Fallback to CWD if not in a git repo
272		}
273		settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
274		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
275		if err != nil {
276			return nil //nolint:nilerr // No settings file means nothing to uninstall
277		}
278	
279		var rawSettings map[string]json.RawMessage
280		if err := json.Unmarshal(data, &rawSettings); err != nil {
281			return fmt.Errorf("failed to parse settings.json: %w", err)
282		}
283	
284		// rawHooks preserves unknown hook types
285		var rawHooks map[string]json.RawMessage
286		if hooksRaw, ok := rawSettings["hooks"]; ok {
287			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
288				return fmt.Errorf("failed to parse hooks: %w", err)
289			}
290		}
291		if rawHooks == nil {
292			rawHooks = make(map[string]json.RawMessage)
293		}
294	
295		// Parse only the hook types we need to modify
296		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
297		parseHookType(rawHooks, "SessionStart", &sessionStart)
298		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
299		parseHookType(rawHooks, "Stop", &stop)
300		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
301		parseHookType(rawHooks, "PreToolUse", &preToolUse)
302		parseHookType(rawHooks, "PostToolUse", &postToolUse)
303		parseHookType(rawHooks, "PreCompact", &preCompact)
304	
305		// Remove Entire hooks from all hook types
306		sessionStart = removeEntireHooks(sessionStart)
307		sessionEnd = removeEntireHooks(sessionEnd)
308		stop = removeEntireHooks(stop)
309		userPromptSubmit = removeEntireHooks(userPromptSubmit)
310		preToolUse = removeEntireHooks(preToolUse)
311		postToolUse = removeEntireHooks(postToolUse)
312		preCompact = removeEntireHooks(preCompact)
313	
314		// Marshal modified hook types back to rawHooks
315		marshalHookType(rawHooks, "SessionStart", sessionStart)
316		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
317		marshalHookType(rawHooks, "Stop", stop)
318		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
319		marshalHookType(rawHooks, "PreToolUse", preToolUse)
320		marshalHookType(rawHooks, "PostToolUse", postToolUse)
321		marshalHookType(rawHooks, "PreCompact", preCompact)
322	
323		// Also remove the metadata deny rule from permissions
324		var rawPermissions map[string]json.RawMessage
325		if permRaw, ok := rawSettings["permissions"]; ok {
326			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
327				// If parsing fails, just skip permissions cleanup
328				rawPermissions = nil
329			}
330		}
331	
332		if rawPermissions != nil {
333			if denyRaw, ok := rawPermissions["deny"]; ok {
334				var denyRules []string
335				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
336					// Filter out the metadata deny rule
337					filteredRules := make([]string, 0, len(denyRules))
338					for _, rule := range denyRules {
339						if rule != metadataDenyRule {
340							filteredRules = append(filteredRules, rule)
341						}
342					}
343					if len(filteredRules) > 0 {
344						denyJSON, err := json.Marshal(filteredRules)
345						if err == nil {
346							rawPermissions["deny"] = denyJSON
347						}
348					} else {
349						// Remove empty deny array
350						delete(rawPermissions, "deny")
351					}
352				}
353			}
354	
355			// If permissions is empty, remove it entirely
356			if len(rawPermissions) > 0 {
357				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
358				if err == nil {
359					rawSettings["permissions"] = permJSON
360				}
361			} else {
362				delete(rawSettings, "permissions")
363			}
364		}
365	
366		// Marshal hooks back (preserving unknown hook types)
367		if len(rawHooks) > 0 {
368			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
369			if err != nil {
370				return fmt.Errorf("failed to marshal hooks: %w", err)
371			}
372			rawSettings["hooks"] = hooksJSON
373		} else {
374			delete(rawSettings, "hooks")
375		}
376	
377		// Write back
378		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
379		if err != nil {
380			return fmt.Errorf("failed to marshal settings: %w", err)
381		}
382		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
383			return fmt.Errorf("failed to write settings.json: %w", err)
384		}
385		return nil
386	}
