434	func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
435		for _, matcher := range matchers {
436			if matcher.Matcher == matcherName {
437				for _, hook := range matcher.Hooks {
438					if hook.Command == command {
439						return true
440					}
441				}
442			}
443		}
