447	func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
448		entry := FactoryHookEntry{Type: "command", Command: command}
449		for i := range matchers {
450			if matchers[i].Matcher == matcherName {
451				matchers[i].Hooks = append(matchers[i].Hooks, entry)
452				return matchers
453			}
454		}
455		return append(matchers, FactoryHookMatcher{Matcher: matcherName, Hooks: []FactoryHookEntry{entry}})
456	}
