463	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
464	func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
465		result := make([]FactoryHookMatcher, 0, len(matchers))
466		for _, matcher := range matchers {
467			filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
468			for _, hook := range matcher.Hooks {
469				if !isEntireHook(hook.Command) {
470					filteredHooks = append(filteredHooks, hook)
471				}
472			}
473			// Only keep the matcher if it has hooks remaining
474			if len(filteredHooks) > 0 {
475				matcher.Hooks = filteredHooks
476				result = append(result, matcher)
477			}
478		}
479		return result
480	}
