332	// configFileName is the Codex config file name.
333	const configFileName = "config.toml"
334	
335	// featureLine is the TOML line that enables the codex_hooks feature.
336	const featureLine = "codex_hooks = true"
337	
338	// ensureProjectFeatureEnabled writes features.codex_hooks = true to the
339	// project-level .codex/config.toml. This keeps the feature flag per-repo.
340	func ensureProjectFeatureEnabled(repoRoot string) error {
341		configPath := filepath.Join(repoRoot, ".codex", configFileName)
342	
343		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
344		if err != nil && !os.IsNotExist(err) {
345			return fmt.Errorf("failed to read config.toml: %w", err)
346		}
347	
348		content := string(data)
349		if strings.Contains(content, featureLine) {
350			return nil
351		}
352	
353		if strings.Contains(content, "[features]") {
354			content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
355		} else {
356			if len(content) > 0 && !strings.HasSuffix(content, "\n") {
357				content += "\n"
358			}
359			content += "\n[features]\n" + featureLine + "\n"
360		}
361	
362		if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
363			return fmt.Errorf("failed to create .codex directory: %w", err)
364		}
365		if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
366			return fmt.Errorf("failed to write config.toml: %w", err)
367		}
368		return nil
369	}
